#!/usr/bin/env bash
# Regenerates linux_<arch>/include from the configure_make build of @jemalloc.
# Run it on a machine of that arch: configure probes the host (LG_PAGE, LG_VADDR).
# The hermetic aarch64 gcc is an aarch64 binary, so an x86_64 host cannot run it.
# linux_arm64 in this repo was generated by running the same configure and make
# inside an arm64 container, with CC pointed at that toolchain.
set -euo pipefail

case "$(uname -m)" in
x86_64) arch=x86_64 ;;
aarch64) arch=arm64 ;;
*) echo "unsupported arch: $(uname -m)" >&2; exit 1 ;;
esac

cd "$(dirname "$0")"
target=@jemalloc//:jemalloc_configure_make
bazel build "$target"
generated=$(bazel cquery --output=files "$target" | grep '/generated$')
src="$(bazel info execution_root)/${generated}/include"
[[ -d "$src" ]] || { echo "no generated headers at $src" >&2; exit 1; }
rm -rf "linux_${arch}"
mkdir -p "linux_${arch}"
cp -r "$src" "linux_${arch}/"
chmod -R u+w "linux_${arch}"
echo "Regenerated linux_${arch}; run: bazel test //deps/jemalloc/..."
